_HEAD = """<link rel="icon" type="image/png" href="/static/favicon.png">
<style>
@font-face { font-family: Roboto; font-weight: 400; font-style: normal; font-display: swap;
             src: url(/static/fonts/roboto-latin-400.woff2) format("woff2"); }
@font-face { font-family: Roboto; font-weight: 500; font-style: normal; font-display: swap;
             src: url(/static/fonts/roboto-latin-500.woff2) format("woff2"); }
:root { --ui-font: Roboto, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; }
html, body, button, input, select, textarea { font-family: var(--ui-font); }
.i { fill: currentColor; flex: none; display: inline-block; vertical-align: middle; }
* { scrollbar-color: #3a3a3a transparent; }
</style>"""


def icon(name: str, size: int = 20, cls: str = "i") -> Markup:
    return Markup(f'<svg class="{cls}" viewBox="0 0 24 24" width="{size}" height="{size}" '
                  f'aria-hidden="true"><path d="{ICONS[name]}"/></svg>')


def ui_head() -> Markup:
    return Markup(_HEAD)


def ui_icons_js() -> Markup:
    return Markup("<script>const MDI = " + json.dumps(ICONS) + ";\n"
                  "function mdi(n, s = 20, c = 'i') { return `<svg class=\"${c}\" viewBox=\"0 0 24 24\" "
                  "width=\"${s}\" height=\"${s}\" aria-hidden=\"true\"><path d=\"${MDI[n]}\"/></svg>`; }</script>")


def install(app):
    app.jinja_env.globals.update(icon=icon, ui_head=ui_head, ui_icons_js=ui_icons_js)
